#!/usr/bin/env python3
import hashlib
import json
import requests
from Crypto.Cipher import AES
from binascii import hexlify, unhexlify
import gmpy2
from collections import defaultdict

# Constants
N = int("00ab76f585834c3c2b7b7b2c8a04c66571539fa660d39762e338cd8160589f08e3d223744cb7894ea6b424ebab899983ff61136c8315d9d03aef12bd7c0486184945998ff80c8d3d59dcb0196fb2c37c43d9cbff751a0745b9d796bcc155cfd186a3bb4ff6c43be833ff1322693d8f76418a48a51f43d598d78a642072e9fff533", 16)
g = 2
k = 3

def get_B_salt(username, A):
    try:
        url = 'http://crypto.chal.csaw.io:5000'
        data = {
            'username': username,
            'token1': str(A)
        }
        response = requests.post(url, data=data)
        text = response.text.strip()

        if response.headers.get('content-type') == 'application/json':
            json_data = response.json()
            return int(json_data['token2']), int(json_data['nacl'])
        else:
            if ':' in text:
                parts = text.split(':')
                if len(parts) >= 2:
                    return int(parts[0]), int(parts[1])
        return None, None
    except Exception as e:
        print(f"Error: {e}")
        return None, None

def analyze_salt_patterns():
    print("[*] Starting salt pattern analysis...")

    # Get all usernames
    with open('/home/ctfplayer/ctf_files/database.txt', 'r') as f:
        usernames = [line.strip() for line in f.readlines() if line.strip()]

    print(f"[*] Found {len(usernames)} users")

    # Test with A=1 for each user to get salt patterns
    salt_patterns = defaultdict(list)
    for username in usernames:
        B, salt = get_B_salt(username, 1)
        if salt is not None:
            salt_patterns[salt].append(username)
            print(f"[*] {username}: salt = {salt}")

    # Analyze salt groups
    print("\n[*] Salt groups:")
    for salt, users in salt_patterns.items():
        print(f"Salt {salt}: {len(users)} users")
        if len(users) > 1:
            print(f"Users: {users}")

    # Look for incremental patterns in B values
    salt_to_verify = {}
    for salt, users in salt_patterns.items():
        if len(users) > 1:
            B_values = []
            for username in users:
                B, _ = get_B_salt(username, 1)
                if B is not None:
                    B_values.append(B)

            if len(B_values) > 1:
                diffs = [(B_values[i] - B_values[i-1]) % N for i in range(1, len(B_values))]
                if all(diff == diffs[0] for diff in diffs):
                    print(f"\n[!] Found constant increment {diffs[0]} for salt {salt}")
                    salt_to_verify[salt] = {
                        'increment': diffs[0],
                        'last_B': B_values[-1],
                        'users': users
                    }

    # Now try to predict root's verifier based on these patterns
    if salt_to_verify:
        print("\n[*] Testing predictions for root...")

        # Get encrypted data
        with open('/home/ctfplayer/ctf_files/encrypted.txt', 'r') as f:
            enc_data = f.read().strip()

        mode, iv, ct = enc_data.split(':')
        iv = unhexlify(iv)
        ct = unhexlify(ct)

        # For each salt pattern
        for salt, data in salt_to_verify.items():
            print(f"\n[*] Testing pattern from salt {salt}")
            increment = data['increment']
            last_B = data['last_B']

            # Try next few increments
            for i in range(1, 11):
                pred_B = (last_B + (increment * i)) % N
                print(f"[*] Testing prediction {i}")

                # Try different forms of the key
                key_attempts = [
                    hashlib.sha256(str(pred_B).encode()).digest(),
                    hashlib.sha256(hex(pred_B)[2:].encode()).digest(),
                    # Try the prediction itself as x value
                    hashlib.sha256(str(pred_B % (2**128)).encode()).digest(),
                    hashlib.sha256(hex(pred_B % (2**128))[2:].encode()).digest()
                ]

                for key in key_attempts:
                    try:
                        cipher = AES.new(key, AES.MODE_CBC, iv)
                        pt = cipher.decrypt(ct)
                        if b'flag{' in pt:
                            print(f"[+] Found flag!")
                            print(f"[+] Prediction used: {pred_B}")
                            print(f"[+] Flag: {pt.decode()}")
                            return
                    except:
                        continue

                # Try the reverse direction
                pred_B = (last_B - (increment * i)) % N
                print(f"[*] Testing reverse prediction {i}")

                key_attempts = [
                    hashlib.sha256(str(pred_B).encode()).digest(),
                    hashlib.sha256(hex(pred_B)[2:].encode()).digest(),
                    hashlib.sha256(str(pred_B % (2**128)).encode()).digest(),
                    hashlib.sha256(hex(pred_B % (2**128))[2:].encode()).digest()
                ]

                for key in key_attempts:
                    try:
                        cipher = AES.new(key, AES.MODE_CBC, iv)
                        pt = cipher.decrypt(ct)
                        if b'flag{' in pt:
                            print(f"[+] Found flag!")
                            print(f"[+] Prediction used: {pred_B}")
                            print(f"[+] Flag: {pt.decode()}")
                            return
                    except:
                        continue

def main():
    print("[*] Starting analysis...")
    analyze_salt_patterns()
    print("[-] Analysis complete")

if __name__ == "__main__":
    main()
